// Everything this workflow needs, in one place. Secrets are not here: the SAP password is read from the n8n host's
// environment (SAP_SL_PASSWORD) and the QMS Import key is the n8n credential "QMS Import key".
return [{ json: {
  qmsUrl: 'https://web-production-b4994f55.up.railway.app',     // QMS base URL (no trailing slash)
  slUrl: $env.SAP_SL_URL ?? 'https://sap-b1-server:50000',       // SAP B1 Service Layer base URL
  companyDb: $env.SAP_COMPANY_DB ?? 'SBO_INTEGRA',               // SAP company database
  slUser: $env.SAP_SL_USER ?? 'n8n',                             // Service Layer user (read-only rights are enough)
  slPassword: $env.SAP_SL_PASSWORD ?? '',
  slInsecureTls: true,          // Service Layer often has a self-signed certificate; set false once it has a proper one
  sqlCode: 'QMS_MRREG_SYNC',    // the stored SQLQuery (integrations/n8n/README.md, step 3)
  windowDays: 14,               // every run: receipts registered in the last 14 days (status changes, new lines)
  nightlyWindowDays: 120,       // the 01:00 run looks further back, for late cancellations and closures
  backfillFrom: '',             // manual backfill: e.g. '2026-01-01' (leave empty for normal runs)
  batchSize: 500,               // rows per request to QMS (QMS accepts up to 2000)
}}];

// The Registration Date window, in WIB.
const cfg = $('Config').first().json;
const wib = (d) => new Date(d.getTime() + 7 * 3600 * 1000);
const iso = (d) => wib(d).toISOString().slice(0, 10);
const now = new Date();
const hourWib = wib(now).getUTCHours();
const days = hourWib === 1 ? cfg.nightlyWindowDays : cfg.windowDays;
const from = cfg.backfillFrom || iso(new Date(now.getTime() - days * 86400 * 1000));
const to = iso(now);
return [{ json: { ...cfg, from, to } }];

// SAP Business One Service Layer: log in, run the stored query for the window (all pages), log out.
// If your n8n reaches HANA directly (ODBC/JDBC node), replace this node with that node running
// integrations/sap/mrreg_and_pos_sync.sql and keep the rest of the workflow.
const c = $input.first().json;
const base = c.slUrl.replace(/\/$/, '') + '/b1s/v1/';
const tls = { skipSslCertificateValidation: !!c.slInsecureTls };
const login = await this.helpers.httpRequest({ method: 'POST', url: base + 'Login', json: true, returnFullResponse: true, ...tls,
  body: { CompanyDB: c.companyDb, UserName: c.slUser, Password: c.slPassword } });
const cookies = [].concat(login.headers['set-cookie'] ?? []).map((x) => x.split(';')[0]);
if (!cookies.some((x) => x.startsWith('B1SESSION='))) cookies.push('B1SESSION=' + login.body.SessionId);
const headers = { Cookie: cookies.join('; '), Prefer: 'odata.maxpagesize=500' };
const ymd = (s) => s.replaceAll('-', '');
const body = { ParamList: `from='${ymd(c.from)}'&to='${ymd(c.to)}'` };
const rows = [];
let next = `SQLQueries('${c.sqlCode}')/List`;
try {
  for (let page = 0; next && page < 1000; page++) {
    const r = await this.helpers.httpRequest({ method: 'POST', url: base + next, json: true, headers, body, ...tls });
    rows.push(...(r.value ?? []));
    next = r['odata.nextLink'] ?? r['@odata.nextLink'] ?? null;
  }
} finally {
  await this.helpers.httpRequest({ method: 'POST', url: base + 'Logout', headers, ...tls }).catch(() => {});
}
return [{ json: { from: c.from, to: c.to, batchSize: c.batchSize, qmsUrl: c.qmsUrl, rows } }];

// One item per request to QMS. An empty window still sends one empty batch, so every run is logged in QMS.
const { rows, from, to, batchSize, qmsUrl } = $input.first().json;
const out = [];
for (let i = 0; i < Math.max(rows.length, 1); i += batchSize) {
  out.push({ json: { qmsUrl, payload: { window: { from, to }, rows: rows.slice(i, i + batchSize) } } });
}
return out;

// What QMS did with the run. Skipped rows are listed so someone can fix them in SAP.
const res = $input.all().map((i) => i.json);
const sum = (f) => res.reduce((t, r) => t + (f(r) ?? 0), 0);
const skipped = res.flatMap((r) => r.skipped ?? []);
return [{ json: {
  batches: res.map((r) => r.batch),
  rows: sum((r) => r.rows),
  receiptsNew: sum((r) => r.mrregs?.inserted), receiptsUpdated: sum((r) => r.mrregs?.updated),
  linesNew: sum((r) => r.lines?.inserted), linesUpdated: sum((r) => r.lines?.updated),
  unmappedBranches: [...new Set(res.flatMap((r) => r.branchesUnmapped ?? []))],
  skipped,
  ok: skipped.length === 0,
}}];
